-- Yaposan 116.0 — payment integrity, moderation appeals, youth-safety defaults.
CREATE TABLE IF NOT EXISTS payment_reconciliations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_user_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL DEFAULT 'stripe', provider_event_id text NOT NULL UNIQUE, kind text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, gross_cents integer NOT NULL DEFAULT 0, platform_fee_cents integer NOT NULL DEFAULT 0, creator_net_cents integer NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'USD', status text NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_payment_reconciliations_creator ON payment_reconciliations(creator_user_id,status,created_at DESC);
CREATE TABLE IF NOT EXISTS moderation_appeals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, resource_type text NOT NULL, resource_id text NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'open', reviewed_by_principal_id uuid REFERENCES admin_principals(id) ON DELETE SET NULL, decision_note text, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_moderation_appeals_queue ON moderation_appeals(status,created_at DESC);
CREATE TABLE IF NOT EXISTS user_safety_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, age_band text NOT NULL, guardian_consent_status text NOT NULL, personalized_ads boolean NOT NULL DEFAULT false, unknown_dm boolean NOT NULL DEFAULT false, live_host boolean NOT NULL DEFAULT false, creator_monetization boolean NOT NULL DEFAULT false, sensitive_media_default text NOT NULL DEFAULT 'blur', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
